import React from "react";

function HowItWorks() {
  const steps = [
    {
      title: "1. Intake & Scanning",
      description: "Capture the ingredients list on a food product package using your device webcam, or select and upload a picture from your local file storage.",
      icon: "📸"
    },
    {
      title: "2. Optical Character Recognition (OCR)",
      description: "The captured or uploaded image is processed locally on your client machine using Tesseract.js. This translates the pixel image into editable text.",
      icon: "⚡"
    },
    {
      title: "3. INS Code Detection",
      description: "The backend receives the raw text and scans it using specialized regex patterns to detect digit codes, bracket codes, and common notation schemas.",
      icon: "🔎"
    },
    {
      title: "4. Database Lookup",
      description: "Extracted codes are queried against the local SQLite database. This pulls baseline risk parameters, safety evaluations, descriptions, and warnings.",
      icon: "💾"
    },
    {
      title: "5. Risk Calculation",
      description: "Our decaying-contribution engine processes all matching items. It tallies scores, applies count bonuses, enforces high-risk thresholds, and defines risk levels.",
      icon: "⚙️"
    },
    {
      title: "6. Interactive Dashboard",
      description: "Results are returned as a unified dashboard: animated risk indicator, detailed additive information cards, high-risk flags, and overall risk bullet reasons.",
      icon: "📊"
    }
  ];

  return (
    <div className="about-page">
      <div className="hero-section text-center">
        <h1>How SAFE BITE Works</h1>
        <p className="hero-subtitle">
          Follow the technology pipeline from capturing ingredient labels to full toxicological indicators.
        </p>
      </div>

      <div className="about-container">
        <div className="pipeline-container">
          {steps.map((step, idx) => (
            <div key={idx} className="pipeline-card card glass">
              <div className="pipeline-icon">{step.icon}</div>
              <div className="pipeline-info">
                <h3>{step.title}</h3>
                <p>{step.description}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="info-card card glass text-center">
          <h2>Why Choose SAFE BITE?</h2>
          <p>
            By combining client-side OCR capabilities with a fast SQLite index backend, SAFE BITE delivers real-time results without uploading your photos to remote storage, preserving data privacy while checking safety.
          </p>
        </div>
      </div>
    </div>
  );
}

export default HowItWorks;
